      outlook: "【7/29朝の更新】朝時点の材料を整理すると、7/29は『地震復旧関連の買い』と『半導体の戻り売り』の綱引きになりやすい。指数はCME先物62,545円(大阪比+145円)・ナイトセッション62,420円(+20円)と横ばい圏で、先物市場は地震をパニック的には織り込んでいない。ただし米SOX指数が-4.49%と4日続落し弱気相場入りしたため、半導体の下押しは続く可能性がある。もっとも米国はメモリー系(マイクロン-8.86%、AMD-8.10%)と非メモリー系(エヌビディア+0.25%、ブロードコム-0.61%)で明確に選別しており、東京でも一律の売りではなく銘柄選別が効く展開が想定される。地震材料はTSMC熊本工場が『段階的に操業再開』と発表したことで供給網の最悪シナリオは回避された一方、東京エレクトロンが九州2事業所の7/29終日停止を明言し、ソニー・ルネサス・三菱電機は点検結果が未発表で、寄り付き前後の会社発表で方向が変わり得る。日本製紙・イオンモール・JR九州のように実害が判明した銘柄と、夜間PTSで広く買われた復旧関連(ヤマックス+16.6%、日特建設+8.0%、不動テトラ+7.9%、鹿島+5.7%)とで明暗が分かれやすい。加えて7/29は7月の権利付き最終売買日にあたり、引け後にはアドバンテストなど62社の決算、日本時間7/30未明にFOMC結果とウォーシュFRB議長会見が控える。気象庁が今後1週間程度(特に2〜3日)は最大震度7程度の地震に注意と呼びかけている点は、大型余震が出れば前提が一気に崩れるリスクとして意識しておきたい。 ── 以下は7/28引け後時点の見立て。7/29(水)は、大引け後に発生した熊本地震(M7.1・最大震度7)がどう織り込まれるかが最大の焦点になる。TSMC熊本工場(JASM)が稼働を停止し、ソニー・富士フイルムの菊陽町拠点でも従業員が避難しており、九州に生産拠点を持つ半導体・電子部品の供給網への影響が意識されやすい。ただし7/28夜の時点で各社の被害・稼働状況の詳細は未確認で、寄り付き前に会社発表が相次げば方向が一変し得る点に注意したい。2016年熊本地震(4/14前震・4/16本震)では、翌営業日の日経平均は63円安と限定的だったが、週明けには九州拠点の生産停滞懸念から一時500円超下落し終値572円安となり、一方で復興・インフラ関連が買われる一方で九州に拠点を持つ製造業と保険が売られる傾向が見られた(あくまで過去事例であり今回の展開を示すものではない)。加えて7/28の半導体総崩れ(キオクシアはストップ安売り気配を残して引け)の余波が続くか自律反発が入るかも読みにくく、7/29にはアドバンテスト、7/30に東京エレクトロン、7/31にキオクシアの決算が控える。米FOMC(7/28〜29)の結果判明は日本時間7/30未明、7/30〜31には日銀金融政策決定会合が控えており、イベント前の様子見と地震材料が交錯する落ち着かない地合いが想定される。",
