      note: "【7/29朝の更新】夜間の情報を反映してプランを見直した。指数はCME先物62,545円(大阪比+145円)と横ばい圏で、先物は地震をパニック的には織り込んでいない。一方で米SOX指数が-4.49%と4日続落したため半導体の逆風は続く。地震はTSMC熊本工場が『段階的に操業再開』と発表し供給網の最悪シナリオは回避された反面、東京エレクトロンは九州2事業所の7/29終日停止を明言し、ソニー・ルネサス・三菱電機は点検結果が未発表と不確実性が残る。夜間PTSでは好決算組(キーエンス+8.25%、カプコン+5.41%)と地震復旧関連(ヤマックス+16.64%、日特建設+7.99%、不動テトラ+7.92%、鹿島+5.74%、ショーボンド+4.89%)が広く買われた。新たに、上方修正と増配を発表しながらPTSで-13.44%と売られたSCREEN HD(7735)を売り警戒として3位に追加し、地震関連への物色の広がりが確認できたショーボンドのスコアを48→54に引き上げた。以下は投資助言ではなく参考シナリオである。 ── 以下は7/28引け後時点の整理。7/28は日経平均-3.95%(-2,566円)の全面安で、メモリー供給過剰懸念からキオクシアがストップ安、SUMCO-16.5%、レーザーテック-14.1%と半導体が総崩れになった。そのうえ大引け後の16時27分に熊本県でM7.1・最大震度7の地震が発生し、TSMC熊本工場(JASM)が稼働を停止、ソニー・富士フイルムの菊陽町拠点でも従業員が避難している。翌7/29は『半導体の下げが続くか自律反発するか』と『地震材料をどこまで織り込むか』の2軸で振られやすく、さらにFOMC(結果は7/30未明)を控えて方向が定まりにくい。こうした地合いでは無理にポジションを取らない判断も選択肢になる。以下は7/28引け後の決算・IR、当日の値動き、SNSでの言及、地震関連情報を突き合わせた参考シナリオであり、投資助言ではない。地震関連としてPTSで買われている銘柄の多くは当日売買代金が0.1〜0.8億円と極端に薄く、流動性ルール(10億円以上)を満たさないためプラン化していない。",
