      outlook: "【7/24 朝7時更新】東京市場は大幅安からのスタートが基本シナリオ。大取ナイト先物65,430円は現物比992円安で、寄り付きは日経平均65,400〜65,600円近辺が目安。下げの主因は米ハイテク(アルファベット・テスラ)の決算失望とAI過剰投資懸念であり、AI・データセンター関連や高PER・高値圏の銘柄ほど影響を受けやすい。一方、①SOX指数の下げが-0.54%と限定的で引け後のインテル決算が良好、②WTI91.87ドル・ブレント100ドル台の原油高、③ドル円163.86円の円安、という3点から、半導体は指数ほど崩れない可能性があり、石油・資源・海運・防衛・輸出関連は逆行高の候補となる。日程面では8:30に6月全国CPI(予想1.7%・前回1.5%)、9:30に7月PMI速報値。CPIが上振れれば日銀の追加利上げ観測から銀行株が買われる一方、内需・不動産には逆風。引け後には信越化学工業(4063)の1Qと中外製薬(4519)の2Qなど計17社の決算が控え、半導体材料・医薬は引けにかけてポジション調整が入りやすい。海外は22:45に米製造業PMI速報値、23:00に米新築住宅販売件数。大幅ギャップダウン局面では寄り直後の値動きが荒くなりやすく、寄り成行は特に不利になりやすい点に留意。／以下は7/23夕方時点の見通し: 7/24(金)は朝方に6月全国消費者物価指数(CPI)の発表が控え、日銀の利上げペース観測と円相場を通じて銀行・内需株に影響が出やすい。国内では信越化学工業(4063)・中外製薬(4519)などの決算が予定され、海外では欧米7月PMI速報値、米6月新築住宅販売、アメリカン・エキスプレス／ベライゾンの決算が控える。7/23の引け後は上方修正ラッシュとなり、KOA(6999)がPTS+19%、ディスコ(6146)が1Q経常+42.5%と好内容を出しており、朝方は決算個別中心の物色になりやすい。ただし7/23の値動きが典型的な寄り天で戻り売り圧力の強さを示したこと、10日移動平均線が上値の壁となっていることから、指数の上値追いには慎重さが必要。中東情勢・原油高・163円台の円安への介入警戒も引き続き波乱要因。",
