      outlook: "【朝7:00更新】CME日経225先物は65,080円と大阪日中終値64,141円を約940円上回っており、東京は1,000円近い大幅ギャップアップでのスタートを織り込む水準にある。背景は7/20の米市場でSOX指数が+0.60%(場中一時+3%超)と4日ぶりに反発したことで、ダウ・ナスダックが3日続落するなか半導体だけが買われた形。7/17に日経を1,764円押し下げた東エレク・アドテスト・SBG・キオクシアの4銘柄が買い戻されれば指数の戻りは大きくなる一方、SOX自体は6/22高値から-20%の弱気相場入りを解消したわけではなく、ギャップアップ後に寄り天となるリスクも同時に高い。前回夕方に想定した「非AI・内需へのローテーション継続」というシナリオは、半導体主導の戻りが本物ならむしろ逆回転(内需・ディフェンシブから資金が抜ける)しうる点に留意が必要。以下は前提が変わりうるため、寄り後の半導体主力の動きを確認してからの判断が基本となる。 / 7/17(金)と7/20(月)の米国市場2営業日分をまとめて織り込む形になり、寄り付きのギャップが通常より大きくなりやすい点に留意が必要。7/21当日の国内決算はPCA<9629>・インソース<6200>・令和AH<296A>の3社程度と乏しく、材料はむしろ22日のオービック決算・6月貿易統計・ティアフォー新規上場、23日のディスコ、24日の信越化学・中外製薬・6月CPIと週後半に集中する。米国では21日ノースロップ・グラマン、22日アルファベット/テスラ/TI、23日インテル、22〜23日にECB理事会が控え、AI・半導体関連が反転できるかはこれら決算での設備投資の底堅さ確認が焦点となる。株探/MINKABUによる来週の日経平均予想レンジは62,000〜68,500円前後で、市場では「AI・半導体ラリーは秋口まで休養」との見方も出ている。",
