      outlook: "【朝7:00更新・前提が変わった】昨夕の『強い地合いを引き継ぐ』想定は取り下げる。米3指数は6月PPIの下振れを受けそろって続伸したにもかかわらず、CME日経先物は67,795円と大阪日中終値(68,860円)比で約1,065円安、大阪ナイトも67,600円(-1,260円)まで沈んでおり、寄り付きは1,000円級のギャップダウンが警戒される。逆行の震源は米半導体で、SOX指数が-2.08%、なかでもマイクロンが中国メモリー競合懸念とDRAM供給増観測で-8.02%と急落した。加えて指数寄与度の大きいソフトバンクGのADRが対東京-5.48%で、先物の下げ幅はこの2つでほぼ説明できる。つまり『米国株高＝日本株高』が成立しない朝であり、指数の上昇だけを見て寄りから買い上がるのは危険。物色は二極化が濃く、ASMLが通期上方修正で逆行高(+2.23%)した装置株(東エレク・アドバンテスト・レーザーテック)とメモリー色の濃いキオクシアで明暗が分かれやすい一方、メガバンク・証券はADRが対東京プラスでバリュー買いの受け皿になり得る。後場14:30のTSMC決算は依然として最大の関門で、ギャップダウンで始まった相場がここで一段安になるか切り返すかを左右する。米6月小売売上高・フィラデルフィア連銀指数・新規失業保険申請件数はいずれも日本時間21:30発表で、日中の取引時間には影響しない。地政学面では米・イランの戦闘が再燃しトランプ大統領が攻撃拡大を示唆、ブレントは+1.7%の86.15ドルと3日続伸しており、資源・防衛にはプラス、原油高のコスト増を受ける空運・海運にはマイナス。テクニカルの25日移動平均(69,101円)は完全に上値の遠い水準となり、当面は前日終値68,751円の回復可否が焦点になる。全体としてポジションは軽め、寄りの飛びつきは避け、寄り後の値持ち確認を徹底したい場面。",
